// GANTI dengan chat id Telegram owner (angka). Kirim pesan apa saja ke bot: bot membalas dengan chat id kamu.
const OWNER = 'ISI_CHAT_ID_OWNER'; // boleh angka atau teks

const s = $getWorkflowStaticData('global');
s.queue = s.queue || []; s.seq = s.seq || 0;
const u = $input.first().json;
const out = { chatId: null, text: null, queryId: null };
const push = (id, action, note = '') => { s.seq += 1; s.queue.push({ seq: s.seq, id: Number(id), action, note, ts: new Date().toISOString() }); };

if (u.callback_query) {
  const q = u.callback_query;
  out.queryId = q.id;
  out.chatId = String(q.message.chat.id);
  if (String(q.from.id) !== String(OWNER).trim()) {
    out.text = 'Bot ini khusus owner Zataa.';
  } else {
    const [act, id] = String(q.data || '').split(':');
    if (act === 'ok') { push(id, 'approve'); s.waiting = null; out.text = `✅ #${id} di-approve. Masuk antrian tayang.`; }
    else if (act === 'no') { push(id, 'reject'); s.waiting = null; out.text = `❌ #${id} ditolak.`; }
    else if (act === 'rev') { s.waiting = id; out.text = `✏️ Ketik catatan revisi buat #${id}:`; }
    else if (act === 'boost') { push(id, 'boost'); out.text = `🚀 Boost B${id} disetujui. Fahriah lagi pasang iklannya.`; }
    else if (act === 'skip') { push(id, 'boost_skip'); out.text = `👌 Boost B${id} dilewati.`; }
  }
} else if (u.message) {
  const m = u.message;
  out.chatId = String(m.chat.id);
  const txt = String(m.text || m.caption || '').trim();
  if (String(m.from.id) !== String(OWNER).trim()) {
    out.text = `Chat ID kamu: ${m.chat.id}\nMasukkan angka ini ke node Proses (baris OWNER) di n8n.`;
  } else {
    // balas langsung ke pesan konten (#id) juga dihitung revisi
    const replied = String(m.reply_to_message?.text || m.reply_to_message?.caption || '').match(/#(\d+)/);
    const id = replied ? replied[1] : s.waiting;
    if (txt && !txt.startsWith('/') && id) {
      push(id, 'revision', txt);
      s.waiting = null;
      out.text = `📝 Revisi #${id} dicatat:\n«${txt}»\nTim lagi ngerjain, nanti dikirim ulang ke sini.`;
    } else {
      out.text = 'Halo bos 👋 Konten yang siap otomatis dikirim ke sini.\nTekan ✅ Approve, ✏️ Revisi (lalu ketik catatannya), atau ❌ Tolak. Bisa juga langsung balas (reply) pesan kontennya dengan catatan revisi.';
    }
  }
}
s.queue = s.queue.slice(-300);
return [{ json: out }];

// PC mengirim ?ack=<nomor terakhir yang sudah diproses>; yang sudah di-ack dibuang
const s = $getWorkflowStaticData('global');
s.queue = s.queue || [];
const ack = Number($input.first().json.query?.ack || 0);
s.queue = s.queue.filter((d) => d.seq > ack);
return [{ json: { decisions: s.queue } }];
